import{_ as e,a as r,c as t,ac as p}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"C++ PMR：资源协议、传播与生命周期","description":"按资源接口、所有权、传播和错误实例组织 PMR 说明。","frontmatter":{"title":"C++ PMR：资源协议、传播与生命周期","description":"按资源接口、所有权、传播和错误实例组织 PMR 说明。","showdocs":{"topics":[{"id":"cpp","title":"C++","link":"/topics/cpp/"}],"kind":"知识专题","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"C++ PMR：资源与所有权","summary":"按资源接口、所有权、传播和错误实例组织 PMR 说明。","status":"active","related":[{"title":"C++ 构建排错：头文件、包发现、配置与规模","link":"/programming/cpp/plus/troubleshooting/build-diagnostics","kind":"排错","scope":"general","audience":"general"},{"title":"C++ 完整 SPSC 实践：固定载荷、回绕与双线程测试","link":"/programming/cpp/plus/practice/spsc-application","kind":"开发实践","scope":"general","audience":"general"},{"title":"C++ 完整 SPSC 实践：固定载荷、回绕与双线程测试 · SPSC示例怎样构建且区分预期与执行至一手资料与验证边界","link":"/programming/cpp/plus/practice/spsc-application-part-03","kind":"开发实践","scope":"general","audience":"general"},{"title":"C++ 完整 SPSC 实践：固定载荷、回绕与双线程测试 · SPSC完整工程怎样传输和校验消息","link":"/programming/cpp/plus/practice/spsc-application-part-01","kind":"开发实践","scope":"general","audience":"general"},{"title":"C++ 完整 SPSC 实践：固定载荷、回绕与双线程测试 · SPSC完整项目的头文件入口测试怎样共享源码","link":"/programming/cpp/plus/practice/spsc-application-part-02","kind":"开发实践","scope":"general","audience":"general"}],"prev":false,"next":{"text":"C++ PMR完整实践：复用 C 定长池","link":"/programming/cpp/plus/practice/pmr-application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"C++ PMR完整实践：复用 C 定长池","link":"/programming/cpp/plus/practice/pmr-application"}},"headers":[],"relativePath":"programming/cpp/pmr-resources.md","filePath":"programming/cpp/pmr-resources.md"}'),o={name:"programming/cpp/pmr-resources.md"};function l(s,a,i,c,n,m){return r(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="c-pmr-资源协议、传播与生命周期" tabindex="-1">C++ PMR：资源协议、传播与生命周期 <a class="header-anchor" href="#c-pmr-资源协议、传播与生命周期" aria-label="Permalink to &quot;C++ PMR：资源协议、传播与生命周期&quot;">​</a></h1><h2 id="part-1" tabindex="-1">资源协议与上游分配 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;资源协议与上游分配 {#part-1}&quot;">​</a></h2><p>先理解 RAII、容器与分配/释放配对。本节沿<a href="/programming/cpp/plus/practice/pmr-application#source">slab_resource.hpp 的资源适配器</a>解释 PMR 协议和上游路由，示例未执行。</p><p>专题入口：<a href="#part-1">C++ PMR：资源协议与上游分配</a> · <a href="#part-2">C++ PMR：传播、等价与资源生存期</a> · <a href="/programming/cpp/plus/practice/pmr-application">C++ PMR完整实践：复用 C 定长池</a> · <a href="#part-3">C++ PMR排错：悬空资源、错误归还与误测</a></p><h3 id="part-1-scope" tabindex="-1">C++PMR工程采用什么语言标准 <a class="header-anchor" href="#part-1-scope" aria-label="Permalink to &quot;C++PMR工程采用什么语言标准 {#part-1-scope}&quot;">​</a></h3><p>C++PMR工程采用什么语言标准：采用 C++20 和 C11，不依赖第三方库。PMR自C++17进入标准库，本工程选择C++20作为教学标准，并非使用最新工作草案的所有新增接口。资源是运行时策略对象；std::pmr容器类型不因资源实例不同而改变，适合在同一调用接口选择分配策略。</p><h3 id="part-1-protocol" tabindex="-1">C++memory_resource的三个操作是什么 <a class="header-anchor" href="#part-1-protocol" aria-label="Permalink to &quot;C++memory_resource的三个操作是什么 {#part-1-protocol}&quot;">​</a></h3><p>C++memory_resource的三个操作是什么：派生类实现 do_allocate、do_deallocate 和do_is_equal，公共接口负责转发。allocate必须给出满足大小及对齐的存储或抛出适当异常；deallocate必须收到原指针及匹配bytes/alignment，存储此前未归还，资源等价。资源管理存储，容器负责构造析构元素；把C返回地址直接看作已构造复杂对象是错误的。</p><h3 id="part-1-upstream" tabindex="-1">C++池空时如何正确转交upstream <a class="header-anchor" href="#part-1-upstream" aria-label="Permalink to &quot;C++池空时如何正确转交upstream {#part-1-upstream}&quot;">​</a></h3><p>C++池空时如何正确转交upstream：支持的小请求也可能因池空走upstream，超大或扩展对齐请求同样转发。释放时必须依据归属选择路径，不能只根据bytes/alignment重算分配决策。这里检查是否精确池块起点，其余按合法PMR契约转给原上游；不为任意无效指针兜底。调用者必须确保上游活得比资源久。</p><h3 id="part-1-tradeoff" tabindex="-1">C++monotonic和pool资源怎样选择 <a class="header-anchor" href="#part-1-tradeoff" aria-label="Permalink to &quot;C++monotonic和pool资源怎样选择 {#part-1-tradeoff}&quot;">​</a></h3><p>C++monotonic和pool资源怎样选择：阶段性批量数据适合monotonic_buffer_resource，单个deallocate不回收，阶段结束release整体释放；容器先销毁，不能在仍持有元素时release。频繁申请归还多种小尺寸可考虑unsynchronized_pool_resource，单线程使用并可能保留空闲块至release或销毁。自制固定池可限制尺寸与预分配量，但要承担契约证明及观测成本，不能默认更快。</p><h3 id="part-1-exercise" tabindex="-1">独立练习 <a class="header-anchor" href="#part-1-exercise" aria-label="Permalink to &quot;独立练习 {#part-1-exercise}&quot;">​</a></h3><p>256字节池空后申请16字节，归还时能否依据16&lt;=256把它放回池？</p><details class="details custom-block"><summary>参考答案（先独立推演）</summary><p>不能；该请求可能来自upstream，必须依据归属归还同一资源。样例用块起点匹配，在合法调用契约下区分来源。</p></details><h3 id="part-1-sources" tabindex="-1">一手资料与边界 <a class="header-anchor" href="#part-1-sources" aria-label="Permalink to &quot;一手资料与边界 {#part-1-sources}&quot;">​</a></h3><p>2026-10-17核对 <a href="https://www.open-std.org/jtc1/sc22/wg14/www/docs/n1570.pdf" target="_blank" rel="noopener noreferrer">WG14 C11 N1570</a> 6.2.8、6.5.6、6.5.8与7.22.3；<a href="https://eel.is/c++draft/mem.res" target="_blank" rel="noopener noreferrer">C++资源协议工作草案</a>用于溯源，滚动草案的新接口不自动纳入C++20；<a href="https://eel.is/c++draft/allocator.requirements" target="_blank" rel="noopener noreferrer">Allocator要求</a>用于核对传播边界。国内资料核读 <a href="https://learn.microsoft.com/zh-cn/cpp/standard-library/memory-resource?view=msvc-170" target="_blank" rel="noopener noreferrer">Microsoft中文memory_resource概览</a>，平台实现说明不推广为所有标准库。项目未编译、未执行，普通静态模板通过不能证明内存安全。</p><h2 id="part-2" tabindex="-1">传播、等价与资源生存期 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;传播、等价与资源生存期 {#part-2}&quot;">​</a></h2><p>先读前节资源协议，再比较容器复制、移动与 swap 对资源身份的要求。资源类和测试见<a href="/programming/cpp/plus/practice/pmr-application#source">完整项目源码</a>，示例未执行。</p><p>专题入口：<a href="#part-1">C++ PMR：资源协议与上游分配</a> · <a href="#part-2">C++ PMR：传播、等价与资源生存期</a> · <a href="/programming/cpp/plus/practice/pmr-application">C++ PMR完整实践：复用 C 定长池</a> · <a href="#part-3">C++ PMR排错：悬空资源、错误归还与误测</a></p><h3 id="part-2-lifetime" tabindex="-1">C++PMR资源和容器谁必须先销毁 <a class="header-anchor" href="#part-2-lifetime" aria-label="Permalink to &quot;C++PMR资源和容器谁必须先销毁 {#part-2-lifetime}&quot;">​</a></h3><p>C++PMR资源和容器谁必须先销毁：容器必须先销毁，再销毁资源，最后才释放资源借用的上游。局部变量按构造逆序销毁，因此先声明资源再声明容器；把容器从函数返回却让局部资源结束会留下悬空allocator。shared_ptr管理资源时也要保证容器持有相应拥有关系，单独保存memory_resource裸指针没有延长生存期。</p><h3 id="part-2-equality" tabindex="-1">C++PMR资源相等到底意味着什么 <a class="header-anchor" href="#part-2-equality" aria-label="Permalink to &quot;C++PMR资源相等到底意味着什么 {#part-2-equality}&quot;">​</a></h3><p>C++PMR资源相等到底意味着什么：相等表示两个资源间可以双向释放彼此分配的存储，而不是尺寸、配置或上游相同。本实现只在this地址相同返回true，因为不同实例有独立位图和空闲链；即使它们上游相同也不可以互还池槽。错误声明相等会允许容器转移存储，最终破坏归还路径。</p><h3 id="part-2-copy" tabindex="-1">C++PMR复制容器会沿用原资源吗 <a class="header-anchor" href="#part-2-copy" aria-label="Permalink to &quot;C++PMR复制容器会沿用原资源吗 {#part-2-copy}&quot;">​</a></h3><p>C++PMR复制容器会沿用原资源吗：普通容器复制构造通过select_on_container_copy_construction选择默认资源，不应假定沿用源实例；要确定选择就用带allocator的显式复制构造。默认资源可能被进程其他代码改变，测试应比较resource指针或显式提供目标，不能从输出值相同推断分配位置相同。</p><h3 id="part-2-propagation" tabindex="-1">C++PMR移动赋值和swap如何传播资源 <a class="header-anchor" href="#part-2-propagation" aria-label="Permalink to &quot;C++PMR移动赋值和swap如何传播资源 {#part-2-propagation}&quot;">​</a></h3><p>C++PMR移动赋值和swap如何传播资源：polymorphic_allocator在复制赋值、移动赋值和swap时不传播。移动赋值遇到不等资源可能逐元素移动并在目标资源分配，不能假设只交换指针；无allocator参数的移动构造与此不同。资源不等时直接swap标准容器违反分配器前提，先检查等价，或显式构造目标资源的新容器；泛型强保证不能无条件依赖swap。</p><h3 id="part-2-exercise" tabindex="-1">独立练习 <a class="header-anchor" href="#part-2-exercise" aria-label="Permalink to &quot;独立练习 {#part-2-exercise}&quot;">​</a></h3><p>两个池块宽和上游都相同，能否交换其PMR容器？</p><details class="details custom-block"><summary>参考答案（先独立推演）</summary><p>两个资源仍不等价，不能直接swap；用带目标allocator的复制或逐元素迁移，并重新考虑异常与峰值内存。</p></details><h3 id="part-2-sources" tabindex="-1">一手资料与边界 <a class="header-anchor" href="#part-2-sources" aria-label="Permalink to &quot;一手资料与边界 {#part-2-sources}&quot;">​</a></h3><p>2026-10-17核对 <a href="https://www.open-std.org/jtc1/sc22/wg14/www/docs/n1570.pdf" target="_blank" rel="noopener noreferrer">WG14 C11 N1570</a> 6.2.8、6.5.6、6.5.8与7.22.3；<a href="https://eel.is/c++draft/mem.res" target="_blank" rel="noopener noreferrer">C++资源协议工作草案</a>用于溯源，滚动草案的新接口不自动纳入C++20；<a href="https://eel.is/c++draft/allocator.requirements" target="_blank" rel="noopener noreferrer">Allocator要求</a>用于核对传播边界。国内资料核读 <a href="https://learn.microsoft.com/zh-cn/cpp/standard-library/memory-resource?view=msvc-170" target="_blank" rel="noopener noreferrer">Microsoft中文memory_resource概览</a>，平台实现说明不推广为所有标准库。项目未编译、未执行，普通静态模板通过不能证明内存安全。</p><h2 id="part-3" tabindex="-1">悬空资源、错误归还与误测 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;悬空资源、错误归还与误测 {#part-3}&quot;">​</a></h2><p>先画出容器、资源和上游的拥有顺序，再对照<a href="/programming/cpp/plus/practice/pmr-application#source">资源实现及 test_resource.cpp</a>定位悬空或错误归还；本节不提供性能实测数据。</p><p>专题入口：<a href="#part-1">C++ PMR：资源协议与上游分配</a> · <a href="#part-2">C++ PMR：传播、等价与资源生存期</a> · <a href="/programming/cpp/plus/practice/pmr-application">C++ PMR完整实践：复用 C 定长池</a> · <a href="#part-3">C++ PMR排错：悬空资源、错误归还与误测</a></p><h3 id="part-3-dangling" tabindex="-1">C++PMR容器离开函数后为什么崩溃 <a class="header-anchor" href="#part-3-dangling" aria-label="Permalink to &quot;C++PMR容器离开函数后为什么崩溃 {#part-3-dangling}&quot;">​</a></h3><p>C++PMR容器离开函数后为什么崩溃：先查返回容器是否绑定函数内的局部资源，资源结束后allocator裸指针悬空，下一次扩容或析构都会访问失效对象。修复要让拥有者把资源与容器一起管理，并保证逆序销毁；复制容器时显式选择长寿命目标资源也是一种边界方案。只给容器加shared_ptr不能自动延长资源寿命。</p><h3 id="part-3-deallocate" tabindex="-1">C++PMR归还时bytes不一致会怎样 <a class="header-anchor" href="#part-3-deallocate" aria-label="Permalink to &quot;C++PMR归还时bytes不一致会怎样 {#part-3-deallocate}&quot;">​</a></h3><p>C++PMR归还时bytes不一致会怎样：deallocate的前提要求原始bytes与alignment一致，即使本池当前没用这两个值也不能随便传0或sizeof指针。上游可能按尺寸选择释放路径，错误大小是调用契约违例。记录原请求元组和资源身份定位问题；不要靠捕获异常修复，因为deallocate不能抛异常，违例也没有可恢复保证。</p><h3 id="part-3-terminate" tabindex="-1">C++PMR析构触发terminate怎样定位 <a class="header-anchor" href="#part-3-terminate" aria-label="Permalink to &quot;C++PMR析构触发terminate怎样定位 {#part-3-terminate}&quot;">​</a></h3><p>C++PMR析构触发terminate怎样定位：本教学资源在析构时发现live非零就terminate，先查看尚未销毁的容器、直接allocate的未归还块和资源借用关系。这个检查只在资源对象仍合法时有意义，不能保证发现所有悬空访问。析构发生时再试图释放未知类型元素不安全，必须修正上层拥有顺序。</p><h3 id="part-3-measurement" tabindex="-1">C++定长池性能怎样避免误测 <a class="header-anchor" href="#part-3-measurement" aria-label="Permalink to &quot;C++定长池性能怎样避免误测 {#part-3-measurement}&quot;">​</a></h3><p>C++定长池性能怎样避免误测：先记录节点尺寸、分配次数、池命中率、峰值存活及上游字节，再在相同输入、优化配置和生命周期下比较端到端成本。池查归属的线性扫描、缓存局部性、预分配时间都可能影响结果；把初始化排除时必须同时报告原因。当前只有预期和测试源码，没有基准数据，不声称比标准资源更快。</p><h3 id="part-3-exercise" tabindex="-1">独立练习 <a class="header-anchor" href="#part-3-exercise" aria-label="Permalink to &quot;独立练习 {#part-3-exercise}&quot;">​</a></h3><p>若live归零且demo打印21，能否认定不存在悬空指针或性能改善？</p><details class="details custom-block"><summary>参考答案（先独立推演）</summary><p>不能。计数与校验和只覆盖本次逻辑，旧别名、跨线程误用和未走到的异常路径仍可能存在；性能需单独测量并报告比较边界。</p></details><h3 id="part-3-sources" tabindex="-1">一手资料与边界 <a class="header-anchor" href="#part-3-sources" aria-label="Permalink to &quot;一手资料与边界 {#part-3-sources}&quot;">​</a></h3><p>2026-10-17核对 <a href="https://www.open-std.org/jtc1/sc22/wg14/www/docs/n1570.pdf" target="_blank" rel="noopener noreferrer">WG14 C11 N1570</a> 6.2.8、6.5.6、6.5.8与7.22.3；<a href="https://eel.is/c++draft/mem.res" target="_blank" rel="noopener noreferrer">C++资源协议工作草案</a>用于溯源，滚动草案的新接口不自动纳入C++20；<a href="https://eel.is/c++draft/allocator.requirements" target="_blank" rel="noopener noreferrer">Allocator要求</a>用于核对传播边界。国内资料核读 <a href="https://learn.microsoft.com/zh-cn/cpp/standard-library/memory-resource?view=msvc-170" target="_blank" rel="noopener noreferrer">Microsoft中文memory_resource概览</a>，平台实现说明不推广为所有标准库。项目未编译、未执行，普通静态模板通过不能证明内存安全。</p>',49)])])}const u=e(o,[["render",l]]);export{d as __pageData,u as default};
